## Code Example

```typescript
type LogLevel = "debug"|"info"|"warn"|"error";

interface LogRecord {
  level: LogLevel;
  message: string;
  timestamp: number;
  context?: any;
}

interface Destination {
  emit(record: LogRecord): Promise<void>;
}

interface DestinationConfig {
  minLevel: LogLevel;
  formatter?: (record: LogRecord) => string;
}

class Logger {
  private destinations = new Map<string, { destination: Destination; config: DestinationConfig }>();

  register(name: string, destination: Destination, config: DestinationConfig): void {
    this.destinations.set(name, { destination, config });
  }

  unregister(name: string): void {
    this.destinations.delete(name);
  }

  async log(level: LogLevel, message: string, context?: any): Promise<void> {
    const record: LogRecord = {
      level,
      message,
      timestamp: Date.now(),
      context
    };

    const promises = Array.from(this.destinations.entries())
      .filter(([_, { config }]) => this.shouldLog(record.level, config.minLevel))
      .map(async ([_, { destination, config }]) => {
        try {
          const formattedRecord = config.formatter ? config.formatter(record) : record;
          await destination.emit(formattedRecord);
        } catch (error) {
          console.error(`Destination failed:`, error);
        }
      });

    await Promise.allSettled(promises);
  }

  private shouldLog(recordLevel: LogLevel, minLevel: LogLevel): boolean {
    const levels: Record<LogLevel, number> = { debug: 0, info: 1, warn: 2, error: 3 };
    return levels[recordLevel] >= levels[minLevel];
  }
}
```

## Why This Is Asked
Tests the ability to design a runtime-extendable CLI core using a registry and plugin-like commands, focusing on isolation, concurrency, and robust error handling.

## Key Concepts
- Registry pattern
- Runtime extensibility
- Per-run isolation
- Concurrency with Promise.allSettled
- Plugin vs inline trade-offs

## Code Example
```typescript
export interface Command {
  name: string
  description: string
  execute(args: string[], ctx: RunContext): Promise<void>
}
export interface RunContext {
  env: NodeJS.ProcessEnv
}
export class CommandRegistry {
  private factories = new Map<string, () => Command>()
  register(name: string, factory: () => Command) { this.factories.set(name, factory) }
  unregister(name: string) { this.factories.delete(name) }
  create(name: string, ctx: RunContext): Command {
    const f = this.factories.get(name)
    if (!f) throw new Error(`Unknown command: ${name}`)
    return f()
  }
  async run(name: string, rawArgs: string[], ctx: RunContext) {
    const cmd = this.create(name, ctx)
    await cmd.execute(rawArgs, ctx)
  }
}
```

