interface SourceAdapter {
  connect(config: any): Promise<void>;
  read(): AsyncIterable<any>;
  close(): Promise<void>;
}

type AdapterFactory = () => SourceAdapter;

interface AdapterPolicy {
  score(metrics: any): number;
}

class AdapterRegistry {
  private registry = new Map<string, { factory: AdapterFactory; policy: AdapterPolicy }>();
  register(kind: string, factory: AdapterFactory, policy: AdapterPolicy) {
    this.registry.set(kind, { factory, policy });
  }
  getAdapter(kind: string, metrics: any): SourceAdapter {
    const entry = this.registry.get(kind)!;
    // In real code, pick highest score; simplified here
